insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors) values
('N5','～です','Menyatakan identitas atau sifat dengan sopan.','Nomina / adjektiva + です','私は学生です。 Saya pelajar.','Gunakan です setelah 学生, tanpa を.'),
('N5','～ません','Bentuk negatif sopan verba.','Pangkal bentuk ます + ません','今日は行きません。 Hari ini saya tidak pergi.','Jangan menambahkan ません ke bentuk kamus 行く.');
insert into public.passages(id,level,title,body,translation) values ('00000000-0000-4000-8100-000000000000','N5','Kucing di dekat jendela','[私|わたし]の[家|いえ]には[猫|ねこ]がいます。[猫|ねこ]は[毎日|まいにち]、[窓|まど]の[近|ちか]くで[寝|ね]ます。','Di rumah saya ada kucing. Setiap hari kucing itu tidur di dekat jendela.');
