insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors) values
('N4','～たことがある','Menyatakan pengalaman yang pernah terjadi.','Verba bentuk た + ことがある','日本へ行ったことがあります。 Saya pernah pergi ke Jepang.','Bedakan 行ったことがある dan 行くことがある yang berarti kadang pergi.'),
('N4','～ながら','Dua tindakan bersamaan oleh pelaku yang sama.','Pangkal bentuk ます + ながら + tindakan utama','音楽を聞きながら勉強します。 Saya belajar sambil mendengarkan musik.','Tindakan utama diletakkan setelah ながら.');
insert into public.passages(id,level,title,body,translation) values ('00000000-0000-4000-8100-000000000010','N4','Janji setelah kelas','[授業|じゅぎょう]が[終|お]わったら、[図書館|としょかん]で[友達|ともだち]に[会|あ]う[約束|やくそく]をしています。そのあと、[駅|えき]まで[一緒|いっしょ]に[歩|ある]きます。','Setelah kelas selesai, saya berjanji bertemu seorang teman di perpustakaan. Sesudah itu kami akan berjalan bersama sampai stasiun.');
