insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors) values
('N3','～わけではない','Menyangkal kesimpulan atau generalisasi.','Bentuk biasa + わけではない','嫌いなわけではありません。 Bukan berarti saya tidak suka.','Adjektiva な memakai な sebelum わけ.'),
('N3','～に比べて','Membandingkan dengan suatu acuan.','Nomina + に比べて','去年に比べて利用者が増えました。 Pengguna bertambah dibanding tahun lalu.','Gunakan に untuk penanda acuan perbandingan.');
insert into public.passages(id,level,title,body,translation) values ('00000000-0000-4000-8100-000000000020','N3','Perubahan jam buka perpustakaan','[利用者|りようしゃ]の[意見|いけん]を[受|う]けて、[図書館|としょかん]は[土曜日|どようび]の[閉館時間|へいかんじかん]を[一時間|いちじかん][遅|おそ]くした。[平日|へいじつ]の[営業時間|えいぎょうじかん]は[変|か]わらない。','Menanggapi pendapat pengunjung, perpustakaan mengundur jam tutup hari Sabtu satu jam. Jam buka pada hari kerja tetap sama.');
insert into public.listening(id,level,title,path) values ('00000000-0000-4000-8100-000000000021','N3','Mendengar N3','levels/n3.mp3');
insert into public.questions(id,level,prompt,options,passage_id,listening_id,section,placement) values ('00000000-0000-4000-8100-000000000022','N3','去年（　）、今年は利用者が増えた。',array['に比べて','に対してだけ']::text[],null,null,'bunpou',true);
insert into public.answer_keys(question_id,answers,explanation,transcript) values ('00000000-0000-4000-8100-000000000022',array['に比べて']::text[],'に比べて menandai acuan perbandingan.',null);
