insert into public.answer_keys(question_id,answers,explanation,transcript) values ('00000000-0000-4000-8100-000000000023',array['Jam tutup hari Sabtu']::text[],'土曜日の閉館時間 adalah jam tutup hari Sabtu.',null);
insert into public.questions(id,level,prompt,options,passage_id,listening_id,section,placement) values ('00000000-0000-4000-8100-000000000024','N3','Mengapa jadwal pengarahan berubah?',array['Karena kondisi tempat acara','Karena pembicara sakit']::text[],null,'00000000-0000-4000-8100-000000000021','choukai',false);
insert into public.answer_keys(question_id,answers,explanation,transcript) values ('00000000-0000-4000-8100-000000000024',array['Karena kondisi tempat acara']::text[],'会場の都合 menyebut alasan terkait tempat acara.','予定していた説明会は、会場の都合で来週に変更になりました。');
