insert into public.vocabulary(level,japanese,reading,romaji,meaning,topic,part_of_speech,example,example_translation,audio_path) values
('N2','妥当','だとう','datō','wajar','Umum','nomina / adjektiva na','その判断は妥当だと思う。','Menurut saya keputusan itu masuk akal.','words/n2-01.mp3'),
('N2','促進','そくしん','sokushin','dorongan untuk mempercepat','Umum','nomina','自治体は地域交流を促進している。','Pemerintah daerah mendorong pertukaran antarwarga.','words/n2-02.mp3'),
('N2','確保','かくほ','kakuho','pengamanan atau penyediaan','Umum','nomina','会議のために部屋を確保した。','Kami telah menyediakan ruang untuk rapat.','words/n2-03.mp3'),
('N2','概略','がいりゃく','gairyaku','garis besar','Umum','nomina','計画の概略を説明します。','Saya akan menjelaskan garis besar rencana itu.','words/n2-04.mp3'),
('N2','把握','はあく','haaku','pemahaman menyeluruh','Umum','nomina','まず現状を把握する必要がある。','Pertama-tama kita perlu memahami situasi saat ini.','words/n2-05.mp3'),
('N2','顕著','けんちょ','kencho','mencolok','Umum','nomina / adjektiva na','二つの地域には顕著な差がある。','Ada perbedaan mencolok antara kedua wilayah.','words/n2-06.mp3'),
('N2','削減','さくげん','sakugen','pengurangan','Umum','nomina','経費の削減に取り組んでいる。','Kami berupaya mengurangi biaya.','words/n2-07.mp3'),
('N2','充実','じゅうじつ','jūjitsu','pengayaan atau kelengkapan','Umum','nomina','研修制度の充実を図る。','Kami berupaya meningkatkan program pelatihan.','words/n2-08.mp3'),
('N2','普及','ふきゅう','fukyū','penyebarluasan','Umum','nomina','スマートフォンが広く普及した。','Ponsel pintar telah digunakan secara luas.','words/n2-09.mp3'),
('N2','対応','たいおう','taiō','penanganan','Umum','nomina','問い合わせに対応する。','Saya menangani pertanyaan yang masuk.','words/n2-10.mp3');
