insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors) values
('N2','～に伴って','Suatu perubahan terjadi seiring perubahan lain.','Nomina / verba bentuk kamus + に伴って','人口の増加に伴って、交通量も増えた。 Volume lalu lintas meningkat seiring pertambahan penduduk.','Gunakan 伴う untuk hubungan yang menyertai perubahan.'),
('N2','～にすぎない','Menekankan bahwa sesuatu hanya sebatas itu.','Nomina / bentuk biasa + にすぎない','これは一つの例にすぎない。 Ini hanya satu contoh.','Bentuk ini bernuansa membatasi dan biasanya digunakan dalam ragam formal.');
insert into public.passages(id,level,title,body,translation) values ('00000000-0000-4000-8100-000000000030','N2','Evaluasi kebijakan baru','[新|あたら]しい[制度|せいど]の[導入後|どうにゅうご]、[手続|てつづ]きにかかる[時間|じかん]は[短|みじか]くなった。しかし、[申請数|しんせいすう]も[減|へ]っており、[制度|せいど]だけの[効果|こうか]とは[言|い]い[切|き]れない。','Setelah sistem baru diterapkan, waktu pengurusan menjadi lebih singkat. Namun jumlah permohonan juga menurun, sehingga belum bisa dipastikan perubahan itu semata-mata akibat sistem baru.');
insert into public.listening(id,level,title,path) values ('00000000-0000-4000-8100-000000000031','N2','Mendengar N2','levels/n2.mp3');
insert into public.questions(id,level,prompt,options,passage_id,listening_id,section,placement) values ('00000000-0000-4000-8100-000000000032','N2','人口の増加（　）、交通量も増えた。',array['に先立って','に伴って']::text[],null,null,'bunpou',true);
insert into public.answer_keys(question_id,answers,explanation,transcript) values ('00000000-0000-4000-8100-000000000032',array['に伴って']::text[],'に伴って menunjukkan perubahan yang berlangsung seiring.',null);
insert into public.questions(id,level,prompt,options,passage_id,listening_id,section,placement) values ('00000000-0000-4000-8100-000000000033','N2','Mengapa efek sistem belum dapat dipastikan?',array['Jumlah permohonan juga turun','Sistem belum diterapkan']::text[],'00000000-0000-4000-8100-000000000030',null,'dokkai',false);
insert into public.answer_keys(question_id,answers,explanation,transcript) values ('00000000-0000-4000-8100-000000000033',array['Jumlah permohonan juga turun']::text[],'申請数も減っており menyebut faktor lain yang mungkin berpengaruh.',null);
insert into public.questions(id,level,prompt,options,passage_id,listening_id,section,placement) values ('00000000-0000-4000-8100-000000000034','N2','Mengapa cara operasional akan ditinjau?',array['Biaya tidak turun','Beban di lapangan meningkat']::text[],null,'00000000-0000-4000-8100-000000000031','choukai',false);
insert into public.answer_keys(question_id,answers,explanation,transcript) values ('00000000-0000-4000-8100-000000000034',array['Beban di lapangan meningkat']::text[],'現場の負担が増えたため menyatakan alasan.','費用は削減できましたが、現場の負担が増えたため、運用方法を見直す予定です。');
