insert into public.vocabulary(level,japanese,reading,romaji,meaning,topic,part_of_speech,example,example_translation,audio_path) values
('N1','払拭','ふっしょく','fusshoku','penghilangan keraguan atau kekhawatiran','Umum','nomina','説明を尽くして懸念を払拭した。','Penjelasan yang menyeluruh menghilangkan kekhawatiran.','words/n1-01.mp3'),
('N1','逡巡','しゅんじゅん','shunjun','keragu-raguan','Umum','nomina','彼は返答を前にしばらく逡巡した。','Ia sempat ragu sebelum menjawab.','words/n1-02.mp3'),
('N1','忌憚','きたん','kitan','keengganan berterus terang','Umum','nomina','忌憚のないご意見をお聞かせください。','Silakan sampaikan pendapat Anda secara terus terang.','words/n1-03.mp3'),
('N1','斟酌','しんしゃく','shinshaku','pertimbangan atas keadaan','Umum','nomina','個々の事情を斟酌する必要がある。','Keadaan masing-masing orang perlu dipertimbangkan.','words/n1-04.mp3'),
('N1','杜撰','ずさん','zusan','ceroboh atau serampangan','Umum','nomina','杜撰な管理が問題になった。','Pengelolaan yang serampangan menjadi masalah.','words/n1-05.mp3'),
('N1','瑕疵','かし','kashi','cacat atau kekurangan','Umum','nomina','契約の手続きに瑕疵があった。','Ada cacat pada prosedur kontrak.','words/n1-06.mp3'),
('N1','乖離','かいり','kairi','kesenjangan atau penyimpangan','Umum','nomina','計画と実態の乖離が大きい。','Kesenjangan antara rencana dan kenyataan besar.','words/n1-07.mp3'),
('N1','謳歌','おうか','ōka','menikmati sepenuhnya','Umum','nomina','若者たちは青春を謳歌した。','Kaum muda itu menikmati masa mudanya sepenuhnya.','words/n1-08.mp3'),
('N1','憂慮','ゆうりょ','yūryo','keprihatinan','Umum','nomina','専門家は事態の悪化を憂慮している。','Para ahli mengkhawatirkan memburuknya keadaan.','words/n1-09.mp3'),
('N1','看過','かんか','kanka','mengabaikan hal yang seharusnya diperhatikan','Umum','nomina','この矛盾は看過できない。','Kontradiksi ini tidak bisa diabaikan.','words/n1-10.mp3');
