insert into public.grammar_points(level,pattern,explanation,formula,examples,common_errors) values
('N1','～をもって','Menandai waktu resmi berakhir atau dimulainya sesuatu.','Nomina waktu + をもって','本日をもって受付を終了します。 Pendaftaran ditutup terhitung hari ini.','Pola formal ini lazim dipakai pada pengumuman.'),
('N1','～に堪えない','Dalam ungkapan tertentu, menyatakan perasaan yang sangat kuat.','Nomina perasaan + に堪えない','感謝に堪えません。 Saya sangat berterima kasih.','Bedakan 感謝に堪えない dari 見るに堪えない yang berarti tidak sanggup melihat.');
insert into public.passages(id,level,title,body,translation) values ('00000000-0000-4000-8100-000000000040','N1','Menafsirkan hasil survei','[回答|かいとう]の[偏|かたよ]りを[看過|かんか]したまま[調査結果|ちょうさけっか]を[一般化|いっぱんか]すれば、[実態|じったい]との[乖離|かいり]を[招|まね]きかねない。[数字|すうじ]の[見栄|みば]えより、[調査|ちょうさ]の[前提|ぜんてい]を[吟味|ぎんみ]すべきだ。','Menggeneralisasi hasil survei sambil mengabaikan bias jawaban berisiko menghasilkan kesimpulan yang menyimpang dari keadaan nyata. Asumsi survei perlu diperiksa lebih dahulu daripada tampilan angkanya.');
