insert into public.questions(id,level,prompt,options,passage_id,listening_id,section,placement) values ('00000000-0000-4000-8100-000000000044','N1','Apa yang perlu diperjelas selain kesimpulan?',array['Proses sampai pada keputusan','Jumlah peserta rapat']::text[],null,'00000000-0000-4000-8100-000000000041','choukai',false);
insert into public.answer_keys(question_id,answers,explanation,transcript) values ('00000000-0000-4000-8100-000000000044',array['Proses sampai pada keputusan']::text[],'判断に至った経緯 adalah proses atau latar sampai keputusan diambil.','懸念を払拭するには、結論だけでなく、判断に至った経緯も明らかにする必要があります。');
